from booking import cancellation_fee


def test_cancellation_fee_at_and_above_24_hours():
    for hours in (24, 25, 48, 100):
        result = cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 0

from booking import cancellation_fee


def test_cancellation_fee_from_zero_through_23_hours():
    for hours in (0, 12, 23):
        result = cancellation_fee(hours)
        assert isinstance(result, int) and not isinstance(result, bool)
        assert result == 2500

